class TrieNode:
    def __init__(self) -> None:
        self.children: dict[str, TrieNode] = {}
        self.is_end = False  # whether a word ends at this node


class WordDictionary:
    def __init__(self) -> None:
        self.root = TrieNode()

    def add_word(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search(self, pattern: str) -> bool:
        # Whether some word below node matches pattern from position i on.
        def matches(node: TrieNode, i: int) -> bool:
            if i == len(pattern):
                return node.is_end
            ch = pattern[i]
            if ch == ".":
                return any(matches(child, i + 1) for child in node.children.values())
            child = node.children.get(ch)
            return child is not None and matches(child, i + 1)

        return matches(self.root, 0)


