class TrieNode {
  constructor() {
    this.children = new Map(); // a letter to the next node
    this.isEnd = false; // whether a word ends at this node
  }
}

class WordDictionary {
  constructor() {
    this.root = new TrieNode();
  }

  addWord(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }

  search(pattern) {
    return this.matches(this.root, pattern, 0);
  }

  // Whether some word below node matches pattern from position i on.
  matches(node, pattern, i) {
    if (i === pattern.length) {
      return node.isEnd;
    }
    const ch = pattern[i];
    if (ch === ".") {
      for (const child of node.children.values()) {
        if (this.matches(child, pattern, i + 1)) {
          return true;
        }
      }
      return false;
    }
    const child = node.children.get(ch);
    return child !== undefined && this.matches(child, pattern, i + 1);
  }
}

