#include <iostream>
#include <string>

struct TrieNode {
    TrieNode* children[26] = {};  // one per letter, nullptr when missing
    bool isEnd = false;           // whether a word ends at this node
};

class WordDictionary {
public:
    void addWord(const std::string& word) {
        TrieNode* node = &root_;
        for (char ch : word) {
            int i = ch - 'a';
            if (node->children[i] == nullptr) {
                node->children[i] = new TrieNode();
            }
            node = node->children[i];
        }
        node->isEnd = true;
    }

    bool search(const std::string& pattern) {
        return matches(&root_, pattern, 0);
    }

private:
    TrieNode root_;

    // Whether some word below node matches pattern from position i on.
    bool matches(TrieNode* node, const std::string& pattern, std::size_t i) {
        if (i == pattern.size()) {
            return node->isEnd;
        }
        if (pattern[i] == '.') {
            for (TrieNode* child : node->children) {
                if (child != nullptr && matches(child, pattern, i + 1)) {
                    return true;
                }
            }
            return false;
        }
        TrieNode* child = node->children[pattern[i] - 'a'];
        return child != nullptr && matches(child, pattern, i + 1);
    }
};

int main() {
    int q;
    std::cin >> q;
    WordDictionary dictionary;
    for (int i = 0; i < q; i++) {
        std::string op, word;
        std::cin >> op >> word;
        if (op == "addWord") {
            dictionary.addWord(word);
        } else {
            std::cout << (dictionary.search(word) ? "true" : "false") << "\n";
        }
    }
    return 0;
}

