class TrieNode {
    final TrieNode[] children = new TrieNode[26]; // one per letter, null when missing
    boolean isEnd; // whether a word ends at this node
}

class WordDictionary {
    private final TrieNode root = new TrieNode();

    void addWord(String word) {
        TrieNode node = root;
        for (char ch : word.toCharArray()) {
            int i = ch - 'a';
            if (node.children[i] == null) {
                node.children[i] = new TrieNode();
            }
            node = node.children[i];
        }
        node.isEnd = true;
    }

    boolean search(String pattern) {
        return matches(root, pattern, 0);
    }

    // Whether some word below node matches pattern from position i on.
    private boolean matches(TrieNode node, String pattern, int i) {
        if (i == pattern.length()) {
            return node.isEnd;
        }
        char ch = pattern.charAt(i);
        if (ch == '.') {
            for (TrieNode child : node.children) {
                if (child != null && matches(child, pattern, i + 1)) {
                    return true;
                }
            }
            return false;
        }
        TrieNode child = node.children[ch - 'a'];
        return child != null && matches(child, pattern, i + 1);
    }
}

