package main

import "fmt"

// TrieNode has a child for each letter (nil when missing) and marks where a
// word ends.
type TrieNode struct {
	children [26]*TrieNode
	isEnd    bool
}

// WordDictionary stores words in a trie, letter by letter from its root.
type WordDictionary struct {
	root TrieNode
}

func (d *WordDictionary) addWord(word string) {
	node := &d.root
	for _, ch := range word {
		i := ch - 'a'
		if node.children[i] == nil {
			node.children[i] = &TrieNode{}
		}
		node = node.children[i]
	}
	node.isEnd = true
}

func (d *WordDictionary) search(pattern string) bool {
	return matches(&d.root, pattern, 0)
}

// matches reports whether some word below node matches pattern from position i on.
func matches(node *TrieNode, pattern string, i int) bool {
	if i == len(pattern) {
		return node.isEnd
	}
	if pattern[i] == '.' {
		for _, child := range node.children {
			if child != nil && matches(child, pattern, i+1) {
				return true
			}
		}
		return false
	}
	child := node.children[pattern[i]-'a']
	return child != nil && matches(child, pattern, i+1)
}

func main() {
	var q int
	fmt.Scan(&q)
	dictionary := WordDictionary{}
	for i := 0; i < q; i++ {
		var op, word string
		fmt.Scan(&op, &word)
		if op == "addWord" {
			dictionary.addWord(word)
		} else {
			fmt.Println(dictionary.search(word))
		}
	}
}

