import { readFileSync } from "node:fs";

class TrieNode {
  children = new Map<string, TrieNode>();
  isEnd = false; // whether a word ends at this node
}

class WordDictionary {
  private root = new TrieNode();

  addWord(word: string): void {
    let node = this.root;
    for (const ch of word) {
      let child = node.children.get(ch);
      if (child === undefined) {
        child = new TrieNode();
        node.children.set(ch, child);
      }
      node = child;
    }
    node.isEnd = true;
  }

  search(pattern: string): boolean {
    return this.matches(this.root, pattern, 0);
  }

  // Whether some word below node matches pattern from position i on.
  private matches(node: TrieNode, pattern: string, i: number): boolean {
    if (i === pattern.length) {
      return node.isEnd;
    }
    const ch = pattern.charAt(i);
    if (ch === ".") {
      for (const child of node.children.values()) {
        if (this.matches(child, pattern, i + 1)) {
          return true;
        }
      }
      return false;
    }
    const child = node.children.get(ch);
    return child !== undefined && this.matches(child, pattern, i + 1);
  }
}

